    CHECK(std::get<1>(errors[0]).find("արտահայտություն") != std::string::npos);

    // սխալ արտահայտության փոխարեն դրվում է չեզոք հանգույց, և հաջորդ
    // հրամանը վերլուծվում է սովորական ձևով
    auto& sub = onlySub(*prog);
